abstract class Animal {
    String name;

    Animal(String name) {
        this.name = name;
        System.out.print("Animal ");
        makeSound();
    }

    void makeSound() {
        System.out.print("sound ");
    }
}

class Dog extends Animal {
    Dog(String name) {
        super(name);
        System.out.print("Dog ");
    }

    @Override
    void makeSound() {
        System.out.print(name + "-bark ");
    }
}
